import { Injectable } from "@angular/core";
import { FormGroup } from "@angular/forms";
import { NewCard } from "src/app/models/card/new-card.model";
import { ImagesService } from "../external/images/images.service";
import { PexelsResponse } from "src/app/models/pexels/pexels-response.model";
import { Observable, map } from "rxjs";

@Injectable({
    providedIn: 'root'
  })
  export class CardUtils {

    private resultImage: string = '';

    constructor(private imageService: ImagesService){

    }

    public createNewCard(form: FormGroup): NewCard {
        const newCard = new NewCard();
        newCard.title = form.value.titulo;
        newCard.description = form.value.descricao;
        this.sortImages();
        // newCard.image = this.sortImages();
        newCard.image = this.resultImage

        console.log('newCard.image ', newCard.image)
        console.log('this.resultImage ', this.resultImage)


        return newCard;
      }
    
      public sortImages(): void{
        const pagina = this.getRandomNumber(1, 10);
        const imagem = this.getRandomNumber(1, 15);

        this.imageService.getHappyImagesPexels(pagina).subscribe(
            {
                next: (response: PexelsResponse) => {
                    console.log('primeiro response ', response)
                    this.resultImage = response.photos[imagem].src.large
                    console.log('resultado image ', response.photos[imagem].src.large)
                },
                error: (err) => {
                    console.log(err)
                }
            }
        )
        // console.log('resultImage ', resultImage)
        // return resultImage;
      }

    public getRandomNumber(min: number, max: number): number {
        return Math.floor(Math.random() * (max - min + 1)) + min;
    }
  }
